//! ZIP 2005 key derivation with `use_qsk = true` (ZIP 2005, "Usage with FROST", and the changes it
//! makes to the protocol spec § 4.2.3), checked against vectors this crate did not produce.
//!
//! The fixture is `zcash-sign/tests/fixtures/zip2005_use_qsk.json` from ZcashFoundation/frost-tools
//! PR #610 (head 038204d4ff1f58042c54ce55be02336c77e703c6, Apache-2.0), copied byte for byte. Its
//! own description says it was generated by zafe-core and is not official. `derive_use_qsk` was
//! written from the ZIP text, so agreement here is two implementations agreeing, not one checking
//! itself.
#![cfg(feature = "zip2005")]

use konclave_seal::zip2005::{derive_use_qsk, Zip2005Error, QK_CONTEXT};
use orchard::keys::{FullViewingKey, Scope};
use zcash_address::unified::{Encoding, Fvk, Revision, Ufvk, Uitem};
use zcash_protocol::consensus::NetworkType;

const VECTORS: &str = include_str!("fixtures/zip2005_use_qsk.json");

struct Vector {
    sk: [u8; 32],
    ak: [u8; 32],
    nk: Vec<u8>,
    qsk: Vec<u8>,
    qk: Vec<u8>,
    rivk_ext: Vec<u8>,
    fvk: Vec<u8>,
    address: Vec<u8>,
    ufvk_testnet: String,
}

fn hex(s: &str) -> Vec<u8> {
    konclave_seal::hex::decode(s).expect("the fixture holds hex")
}

/// The fixture's vectors, read with a minimal parser for its flat `"key": "value"` lines so the
/// test needs no JSON dependency. Every field is required; a missing one fails the read.
fn vectors() -> Vec<Vector> {
    let mut out = Vec::new();
    for block in VECTORS.split('{').skip(2) {
        let field = |name: &str| -> String {
            let key = format!("\"{name}\": \"");
            let start = block.find(&key).unwrap_or_else(|| panic!("no {name}")) + key.len();
            let end = start + block[start..].find('"').unwrap();
            block[start..end].to_string()
        };
        let arr = |name: &str| -> [u8; 32] { hex(&field(name)).try_into().unwrap() };
        out.push(Vector {
            sk: arr("sk"),
            ak: arr("ak"),
            nk: hex(&field("nk")),
            qsk: hex(&field("qsk")),
            qk: hex(&field("qk")),
            rivk_ext: hex(&field("rivk_ext")),
            fvk: hex(&field("fvk")),
            address: hex(&field("default_address_raw")),
            ufvk_testnet: field("ufvk_testnet"),
        });
    }
    out
}

#[test]
fn the_fixture_names_the_context_string_of_the_zip() {
    assert!(VECTORS.contains(&format!("\"qk_context\": \"{QK_CONTEXT}\"")));
    assert_eq!(QK_CONTEXT, "Zcash ZIP 2005 qk-derivation v1");
}

#[test]
fn every_vector_is_recomputed_from_sk_and_ak() {
    let vs = vectors();
    assert_eq!(vs.len(), 8, "the fixture carries eight vectors");
    for (i, v) in vs.iter().enumerate() {
        let k = derive_use_qsk(&v.sk, &v.ak).unwrap_or_else(|e| panic!("vector {i}: {e:?}"));
        assert_eq!(k.nk.to_vec(), v.nk, "vector {i}: nk");
        assert_eq!(k.qsk.to_vec(), v.qsk, "vector {i}: qsk");
        assert_eq!(k.qk.to_vec(), v.qk, "vector {i}: qk");
        assert_eq!(k.rivk_ext.to_vec(), v.rivk_ext, "vector {i}: rivk_ext");
        assert_eq!(k.fvk.to_vec(), v.fvk, "vector {i}: fvk");

        // What a member would see from it: the default address and the viewing key string.
        let fvk = FullViewingKey::from_bytes(&k.fvk).expect("orchard accepts the key");
        let address = fvk.address_at(0u64, Scope::External);
        assert_eq!(
            address.to_raw_address_bytes().to_vec(),
            v.address,
            "vector {i}: address"
        );
        let ufvk =
            Ufvk::try_from_items(Revision::R0, vec![Uitem::Data(Fvk::Orchard(k.fvk))]).unwrap();
        assert_eq!(
            ufvk.encode(&NetworkType::Test),
            v.ufvk_testnet,
            "vector {i}: UFVK"
        );
    }
}

#[test]
fn a_changed_sk_gives_keys_the_vector_does_not_have() {
    for (i, v) in vectors().iter().enumerate() {
        // The unchanged sk matches first, so a derivation that ignores its input cannot pass.
        let same = derive_use_qsk(&v.sk, &v.ak).expect("the vector derives");
        assert_eq!(same.qsk.to_vec(), v.qsk, "vector {i}: qsk");
        let mut sk = v.sk;
        sk[i % 32] ^= 0x01;
        let k = derive_use_qsk(&sk, &v.ak).expect("any sk derives");
        assert_ne!(k.nk.to_vec(), v.nk, "vector {i}: nk");
        assert_ne!(k.qsk.to_vec(), v.qsk, "vector {i}: qsk");
        assert_ne!(k.qk.to_vec(), v.qk, "vector {i}: qk");
        assert_ne!(k.rivk_ext.to_vec(), v.rivk_ext, "vector {i}: rivk_ext");
    }
}

#[test]
fn rivk_ext_binds_ak() {
    // ak of the next vector: a valid key with an even y, so only the binding can tell them apart.
    let vs = vectors();
    for (i, v) in vs.iter().enumerate() {
        let other = &vs[(i + 1) % vs.len()];
        let k = derive_use_qsk(&v.sk, &other.ak).expect("a valid ak derives");
        assert_eq!(k.nk.to_vec(), v.nk, "vector {i}: nk does not depend on ak");
        assert_eq!(k.qk.to_vec(), v.qk, "vector {i}: qk does not depend on ak");
        assert_ne!(k.rivk_ext.to_vec(), v.rivk_ext, "vector {i}: rivk_ext");
    }
}

#[test]
fn an_ak_with_odd_y_is_refused() {
    // The same x with ỹ = 1 is the negated point: a group key FROST did not normalise.
    for v in vectors() {
        let mut ak = v.ak;
        ak[31] |= 0x80;
        assert_eq!(derive_use_qsk(&v.sk, &ak).err(), Some(Zip2005Error::OddY));
    }
}

#[test]
fn an_ak_that_is_not_a_key_is_refused() {
    let sk = vectors()[0].sk;
    assert_eq!(
        derive_use_qsk(&sk, &[0u8; 32]).err(),
        Some(Zip2005Error::InvalidKey)
    );
    // An x that is not on the curve, with ỹ = 0: find one rather than trust a literal.
    let mut ak = [0u8; 32];
    let off_curve = (1u8..=255)
        .find(|b| {
            ak[0] = *b;
            derive_use_qsk(&sk, &ak).is_err()
        })
        .expect("some small x is not on Pallas");
    ak[0] = off_curve;
    assert_eq!(
        derive_use_qsk(&sk, &ak).err(),
        Some(Zip2005Error::InvalidKey)
    );
}
